export function isDefaultForumPagesText(value) {
    const normalized = String(value || '').trim();
    const forumStructure = STATUS_STRUCTURE_PRESETS.find(item => item.id === 'forum');
    const known = [
        forumStructure?.pagesText,
        LEGACY_FORUM_PAGES_TEXT,
        ...FORUM_SKIN_PRESETS.flatMap(item => item.sections
            ? [item.sections.map(section => section.join('|')).join('\n'), item.sections.slice(0, 4).map(section => section.join('|')).join('\n')]
            : []),
    ].filter(Boolean);
    return !normalized || known.some(item => item.trim() === normalized);
}

