export function parseChatConversationLog(value) {
    return String(value || '')
        .split('§')
        .map(entry => {
            const parts = entry.trim().split('¦').map(part => part.trim());
            if (parts.length < 6) return null;
            const [time, rawSide, rawType, state, duration, ...messageParts] = parts;
            const message = messageParts.join('¦').trim();
            if (!message) return null;
            return {
                time,
                side: ['我', '右', 'right', 'user'].includes(rawSide.toLowerCase()) ? 'right' : 'left',
                type: ['语音', 'voice'].includes(rawType.toLowerCase()) ? 'voice' : 'text',
                state,
                duration,
                message,
            };
        })
        .filter(Boolean);
}

export function parsePages(value) {
    return meaningfulLines(value).map((line, index) => {
        const [label, instruction = ''] = splitLine(line);
        return {
            id: `View${index + 1}`,
            label: label || `角色${index + 1}`,
            instruction: instruction || `填写${label || `角色${index + 1}`}的身份与视角要求`,
        };
    });
}

export function parseFields(value) {
    return meaningfulLines(value).map((line, index) => {
        const [label, instruction = '', rawKind = 'text', rawKey = ''] = splitLine(line);
        const kind = FIELD_KINDS.has(rawKind.toLowerCase()) ? rawKind.toLowerCase() : 'text';
        const stableKey = String(rawKey || `field_${index + 1}`).trim().replace(/[^a-zA-Z0-9_-]/g, '_') || `field_${index + 1}`;
        return {
            id: stableKey,
            label: label || `字段${index + 1}`,
            instruction: instruction || `根据当前剧情填写${label || `字段${index + 1}`}`,
            kind,
        };
    });
}

export function sanitizeTagName(value) {
    const cleaned = String(value ?? '').trim().replace(/[^a-zA-Z0-9_-]/g, '_');
    return cleaned || 'zeya_status';
}

function safeMediaUrl(value, kind = 'image') {
    const url = String(value || '').trim();
    if (!url) return '';
    if (/^https?:\/\//i.test(url) || /^\/(?!\/)/.test(url)) return url;
    if (kind === 'image' && /^data:image\/(?:png|jpe?g|gif|webp|avif);base64,/i.test(url)) return url;
    return '';
}

function normalizePalette(input = {}) {
    const preset = STATUS_PALETTE_PRESETS.find(item => item.id === input.paletteId);
    const source = preset || input.palette || {};
    const color = (key, fallback) => /^#[0-9a-f]{6}$/i.test(String(source[key] || '')) ? String(source[key]) : fallback;
    if (!preset && !input.palette) return null;
    return {
        id: preset?.id || (STATUS_PALETTE_IDS.has(input.paletteId) ? input.paletteId : 'custom'),
        name: preset?.name || '自定义色卡',
        accent: color('accent', '#9b6849'),
        background: color('background', '#f2e5c5'),
        card: color('card', '#f8efd7'),
        text: color('text', '#493a2b'),
        muted: color('muted', '#7a6954'),
    };
}

function normalizeMedia(input = {}) {
    const media = input.media && typeof input.media === 'object' ? input.media : {};
    const avatarSource = ['none', 'character', 'user', 'url'].includes(media.avatarSource) ? media.avatarSource : 'none';
    const archiveImageUrls = [...new Set(
        (Array.isArray(media.archiveImageUrls) ? media.archiveImageUrls : String(media.archiveImageUrls || '').split(/\r?\n/))
            .map(value => safeMediaUrl(value, 'image'))
            .filter(Boolean),
    )].slice(0, 12);
    return {
        avatarSource,
        avatarUrl: safeMediaUrl(media.avatarUrl, 'image'),
        userAvatarUrl: safeMediaUrl(media.userAvatarUrl, 'image'),
        imageUrl: safeMediaUrl(media.imageUrl, 'image'),
        archiveImageUrls,
        audioUrl: safeMediaUrl(media.audioUrl, 'audio'),
        imageAlt: String(media.imageAlt || '状态栏配图').slice(0, 80),
    };
}

function clampNumber(value, minimum, maximum, fallback) {
    const parsed = Number(value);
    return Number.isFinite(parsed) ? Math.max(minimum, Math.min(maximum, parsed)) : fallback;
}

export function normalizePhoneDesktop(input = {}) {
    const source = input.phoneDesktop && typeof input.phoneDesktop === 'object' ? input.phoneDesktop : input;
    const media = input.media && typeof input.media === 'object' ? input.media : {};
    const shellStyle = PHONE_SHELL_STYLES.includes(source.shellStyle) ? source.shellStyle : 'classic';
    const shellDefaults = PHONE_SHELL_VISUAL_DEFAULTS[shellStyle];
    const requestedOrder = Array.isArray(source.widgetOrder) ? source.widgetOrder : [];
    const widgetOrder = [...new Set([...requestedOrder, ...PHONE_WIDGET_IDS])].filter(id => PHONE_WIDGET_IDS.includes(id));
    const requestedWidgetOffsets = source.widgetOffsets && typeof source.widgetOffsets === 'object' && !Array.isArray(source.widgetOffsets)
        ? source.widgetOffsets
        : {};
    const widgetOffsets = Object.fromEntries(PHONE_WIDGET_IDS.map(id => {
        const requested = requestedWidgetOffsets[id] && typeof requestedWidgetOffsets[id] === 'object' ? requestedWidgetOffsets[id] : PHONE_WIDGET_OFFSET_DEFAULTS[id];
        return [id, {
            x: clampNumber(requested.x, -180, 180, 0),
            y: clampNumber(requested.y, -300, 300, 0),
        }];
    }));
    const requestedApps = Array.isArray(source.apps) ? source.apps : [];
    const apps = PHONE_APP_DEFAULTS.map(defaultApp => {
        const custom = requestedApps.find(item => item?.id === defaultApp.id) || {};
        const shellPosition = shellDefaults.appPositions?.[defaultApp.id] || [defaultApp.desktopX, defaultApp.desktopY];
        return {
            id: defaultApp.id,
            name: String(custom.name || defaultApp.name).trim().slice(0, 12) || defaultApp.name,
            iconUrl: safeMediaUrl(custom.iconUrl, 'image'),
            enabled: custom.enabled !== false,
            desktopX: clampNumber(custom.desktopX, 12, 88, shellPosition[0]),
            desktopY: clampNumber(custom.desktopY, 14, 92, shellPosition[1]),
        };
    });
    const requestedPersonalFields = Array.isArray(source.personalFields) ? source.personalFields : [];
    const personalFields = PHONE_PAGE_SCHEMAS[0].fields.map(defaultField => {
        const custom = requestedPersonalFields.find(item => item?.id === defaultField.id) || {};
        return {
            id: defaultField.id,
            label: String(custom.label || defaultField.label).trim().slice(0, 30) || defaultField.label,
            instruction: String(custom.instruction || defaultField.instruction).trim().slice(0, 300) || defaultField.instruction,
            kind: FIELD_KINDS.has(custom.kind) ? custom.kind : defaultField.kind,
        };
    });
    const requestedPageFields = source.pageFields && typeof source.pageFields === 'object' && !Array.isArray(source.pageFields)
        ? source.pageFields
        : {};
    const pageFields = Object.fromEntries(PHONE_PAGE_SCHEMAS.slice(1).map(page => {
        const requestedFields = Array.isArray(requestedPageFields[page.id]) ? requestedPageFields[page.id] : [];
        return [page.id, page.fields.map(defaultField => {
            const custom = requestedFields.find(item => item?.id === defaultField.id) || {};
            return {
                id: defaultField.id,
                label: String(custom.label || defaultField.label).trim().slice(0, 30) || defaultField.label,
                instruction: String(custom.instruction || defaultField.instruction).trim().slice(0, 300) || defaultField.instruction,
                kind: FIELD_KINDS.has(custom.kind) ? custom.kind : defaultField.kind,
            };
        })];
    }));
    const avatarSource = ['none', 'character', 'user', 'url'].includes(source.personalAvatarSource)
        ? source.personalAvatarSource
        : (['none', 'character', 'user', 'url'].includes(media.avatarSource) ? media.avatarSource : 'character');
    const decorationStyle = PHONE_DECORATION_STYLES.includes(source.decorationStyle)
        ? source.decorationStyle
        : source.petalsEnabled === false ? 'none' : shellDefaults.decorationStyle;
    return {
        shellStyle,
        shellColor: /^#[0-9a-f]{6}$/i.test(String(source.shellColor || '')) ? String(source.shellColor) : shellDefaults.shellColor,
        charmUrl: safeMediaUrl(source.charmUrl, 'image'),
        wallpaperUrl: safeMediaUrl(source.wallpaperUrl, 'image'),
        stickerPhotoOneUrl: safeMediaUrl(source.stickerPhotoOneUrl, 'image'),
        stickerPhotoTwoUrl: safeMediaUrl(source.stickerPhotoTwoUrl, 'image'),
        wallpaperPositionX: clampNumber(source.wallpaperPositionX, 0, 100, 50),
        wallpaperPositionY: clampNumber(source.wallpaperPositionY, 0, 100, 50),
        wallpaperScale: clampNumber(source.wallpaperScale, 1, 3, 1),
        decorationStyle,
        petalsEnabled: decorationStyle !== 'none',
        iconScale: clampNumber(source.iconScale, .75, 1.7, shellDefaults.iconScale),
        widgetX: clampNumber(source.widgetX, 8, 42, 15),
        widgetY: clampNumber(source.widgetY, 45, 300, 58),
        widgetOrder,
        widgetOffsets,
        personalAvatarSource: avatarSource,
        personalAvatarUrl: safeMediaUrl(source.personalAvatarUrl || media.avatarUrl, 'image'),
        personalAvatarPositionX: clampNumber(source.personalAvatarPositionX, 0, 100, 50),
        personalAvatarPositionY: clampNumber(source.personalAvatarPositionY, 0, 100, 50),
        personalAvatarScale: clampNumber(source.personalAvatarScale, 1, 3, 1),
        personalFields,
        pageFields,
        apps,
    };
}

export function normalizeRule(input = {}) {
    const pages = parsePages(input.pagesText);
    const sharedFields = parseFields(input.sharedFieldsText);
    const pageFields = parseFields(input.pageFieldsText);
    const structure = STATUS_STRUCTURE_IDS.has(input.structure) ? input.structure : 'custom';
    const structurePreset = STATUS_STRUCTURE_PRESETS.find(item => item.id === structure)
        || STATUS_STRUCTURE_PRESETS.find(item => item.id === 'custom');
    const forumSkin = FORUM_SKIN_IDS.has(input.forumSkin) ? input.forumSkin : 'mist-bbs';
    const forumSkinPreset = FORUM_SKIN_PRESETS.find(item => item.id === forumSkin) || FORUM_SKIN_PRESETS[0];
    const forumStructurePreset = STATUS_STRUCTURE_PRESETS.find(item => item.id === 'forum');
    const normalizedSharedFields = structure === 'forum'
        && forumSkin === 'paranormal-case'
        && !sharedFields.some(field => field.id === FORUM_PRESENCE_FIELD.id)
        ? [...sharedFields, { ...FORUM_PRESENCE_FIELD }]
        : sharedFields;
    const variant = STATUS_CUSTOM_VARIANT_IDS.has(input.variant) ? input.variant : 'auto';
    const chatAppearance = CHAT_APPEARANCE_IDS.has(input.chatAppearance) ? input.chatAppearance : 'kitty-pink';
    const media = normalizeMedia(input);
    const phoneDesktop = normalizePhoneDesktop({ ...input, media });
    const basePages = pages.length
        ? pages
        : parsePages(structure === 'forum' ? forumStructurePreset.pagesText : RULE_PRESETS.relationship.pagesText);
    const usesForumDefaults = structure === 'forum' && isDefaultForumPagesText(input.pagesText);
    const normalizedPages = structure === 'phone'
        ? PHONE_PAGE_SCHEMAS.map(page => ({
            ...page,
            label: phoneDesktop.apps.find(app => app.id === page.id)?.name || page.label,
            fields: (page.id === 'Personal' ? phoneDesktop.personalFields : phoneDesktop.pageFields[page.id]).map(field => ({ ...field })),
        }))
        : (usesForumDefaults && forumSkinPreset.sections
            ? basePages.map((page, index) => ({
                ...page,
                label: forumSkinPreset.sections[index]?.[0] || page.label,
                instruction: forumSkinPreset.sections[index]?.[1] || page.instruction,
            }))
            : basePages);
    const socialAppearance = structure === 'social'
        ? (SOCIAL_APPEARANCE_PRESETS.find(item => item.id === input.theme) || SOCIAL_APPEARANCE_PRESETS[0])
        : null;
    const fallbackStyle = STATUS_STYLE_PRESETS.find(item => item.id === input.theme) || STATUS_STYLE_PRESETS[0];
    const themeAssetUrl = structure === 'social'
        ? safeMediaUrl(input.themeAssetUrl, 'image')
        : '';
    return {
        ruleId: String(input.ruleId || 'zeya-status-rule'),
        ruleName: String(input.ruleName || '双页剧情状态').trim() || '双页剧情状态',
        tagName: sanitizeTagName(input.tagName),
        title: String(input.title || '人物状态记录'),
        subtitle: String(input.subtitle || 'STORY STATUS'),
        theme: socialAppearance?.id || structurePreset.appearanceId || fallbackStyle.id,
        styleName: socialAppearance?.name || structurePreset.appearanceName || fallbackStyle.name,
        themeAssetUrl,
        glyph: structurePreset.glyph,
        structure,
        forumSkin,
        variant,
        chatAppearance,
        chatAppearanceName: CHAT_APPEARANCE_PRESETS.find(item => item.id === chatAppearance)?.name || CHAT_APPEARANCE_PRESETS[0].name,
        chatMascotUrl: CHAT_MASCOT_URL,
        structureName: structurePreset.name,
        palette: normalizePalette(input),
        media,
        phoneDesktop,
        displayOnlyRegex: input.displayOnlyRegex !== false,
        layout: structure === 'social' ? structurePreset.layout : (input.layout === 'stack' ? 'stack' : 'grid'),
        pages: normalizedPages,
        sharedFields: normalizedSharedFields,
        pageFields: pageFields.length ? pageFields : DEFAULT_PAGE_FIELDS,
    };
}

function placeholder(field, pageLabel = '') {
    const subject = pageLabel ? `${pageLabel}·` : '';
    if (field.kind === 'avatar') return `{{${subject}${field.label}：填写头像对应的角色姓名；图片由工坊素材绑定}}`;
    return `{{${subject}${field.label}：${field.instruction}}}`;
}

export function buildAiInstruction(input) {
    const rule = normalizeRule(input);
    if (isStatusBeauty01To15(rule.structure)) return buildStatusBeautyBundledInstruction(rule);
    if (rule.structure === 'forum') {
        const forumGuide = FORUM_SKIN_PRESETS.find(item => item.id === rule.forumSkin)?.aiGuide || FORUM_SKIN_PRESETS[0].aiGuide;
        const forumReplyCount = rule.pageFields.filter(field => /^post_\d+$/.test(field.id)).length;
        const replySlots = Array.from({ length: forumReplyCount }, (_, index) => `R${index + 1}`).join('|');
        const pageSlots = rule.pages.map((page, index) => `${index + 1}${page.label}`).join('/');
        const forumDraft = input?.forumPreviewDrafts?.[rule.forumSkin];
        const fixedTitle = String(forumDraft?.title || '').replace(/[|\[\]<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 60);
        const fixedNotice = String(forumDraft?.notice || '').replace(/[|\[\]<>]/g, '').replace(/\s+/g, ' ').trim().slice(0, 90);
        const fixedIdentity = fixedTitle || fixedNotice
            ? `固定项：${fixedTitle ? `论坛名=${fixedTitle}` : ''}${fixedTitle && fixedNotice ? '；' : ''}${fixedNotice ? `公告=${fixedNotice}` : ''}。`
            : '';
        return [
            `<${rule.tagName}_rules>`,
            `正文后仅追加一份 <${rule.tagName}>；禁代码块、HTML和占位词。`,
            `风格：${forumGuide}`,
            '目的：把{{char}}与{{user}}当本轮故事主角，让网友围观、嗑点、争论、二创和押后续；内容必须接住当前剧情。',
            fixedIdentity,
            `输出 [Shared|论坛名|公告${rule.forumSkin === 'paranormal-case' ? '|在线人数' : ''}]${rule.forumSkin === 'paranormal-case' ? '，在线人数用“在线 X 人”格式' : ''}；N=1至${rule.pages.length}，各写 [ViewN|板块|主题|2-4标签|${replySlots}]，对应${pageSlots}。值内禁用 |、[]、<>。`,
            `R=楼号◆动态昵称◆ID:4-8字符◆MM/DD HH:mm◆正文，可用 >>数字 引用。每页完整 ${forumReplyCount} 楼且楼号连续；主楼4-6句铺场景与冲突，其余每楼1-3句接话推进。`,
            '每页至少4种立场，并从接梗、误会、反驳、嗑点、脑洞、预测中至少写3类；须是可独立阅读的小剧场，禁止情报摘要。',
            `昵称按世界观动态生成，同一网友可沿用同名、至少一半作者不同；预览中的X不是昵称，禁止照搬。共${rule.pages.length}行均须完整。`,
            `</${rule.tagName}_rules>`,
        ].filter(Boolean).join('\n');
    }
    if (isOriginalRoleCardStructure(rule.structure)) {
        const sharedOrder = rule.sharedFields.map(field => field.label).join('|');
        const page = rule.pages[0];
        const pageOrder = (page?.fields || rule.pageFields).map(field => field.label).join('|');
        const purpose = rule.structure === 'archive-status'
            ? '内容：角色公开与隐藏的心声、给user的信、照片画面及本轮签运；用角色第一人称，称呼和署名随剧情生成。'
            : rule.structure === 'pixel-chat'
                ? '内容：角色与user的本轮像素聊天小剧场；标题和副标题要有梗，三句对话须前后连贯并推进情绪。'
                : '内容：按当前剧情填写时间地点、天气、装扮、私密日记和三项待办。';
        return [
            `<${rule.tagName}_rules>`,
            `正文后仅追加一次 <${rule.tagName}>；全部值依据当前剧情动态填写。`,
            purpose,
            '严格按下列顺序，把字段名替换为实际值；每项都要填写，以此类推：',
            `<${rule.tagName}>`,
            rule.sharedFields.length ? `[Shared|${sharedOrder}]` : '',
            `[${page?.id || 'View1'}|${pageOrder}]`,
            `</${rule.tagName}>`,
            '值内禁用 |、[]、<>；禁止代码块、HTML、占位词和第二套状态格式。',
            `</${rule.tagName}_rules>`,
        ].filter(Boolean).join('\n');
    }
    const records = [];
    if (rule.sharedFields.length) {
        records.push(`[Shared|${rule.sharedFields.map(field => placeholder(field)).join('|')}]`);
    }
    for (const page of rule.pages) {
        const fields = page.fields || rule.pageFields;
        records.push(`[${page.id}|${fields.map(field => placeholder(field, page.label)).join('|')}]`);
    }

    const pageGuide = rule.pages.map(page => `- ${page.id} 对应“${page.label}”：${page.instruction}`).join('\n');
    const fieldGuide = rule.pages.some(page => page.fields)
        ? rule.pages.map(page => `${page.label}：${(page.fields || rule.pageFields).map((field, index) => `第${index + 1}项“${field.label}”=${field.instruction}`).join('；')}`).join('\n')
        : rule.pageFields.map((field, index) => `- 第${index + 1}项“${field.label}”：${field.instruction}`).join('\n');
    const valueRule = '方括号内严格使用英文竖线分隔。值中不得出现英文竖线、方括号、尖括号或 Markdown 加粗。';
    return [
        `<${rule.tagName}_rules>`,
        `每次正文结束后，必须追加一个 <${rule.tagName}> 状态区块。`,
        '区块中的所有值都必须根据当前剧情动态生成；模板中的双花括号只是填写说明，回复时不得原样保留。',
        valueRule,
        '不要把状态区块放进 Markdown 代码块，不要输出 HTML，不要遗漏记录，也不要附加同类的第二套状态格式。',
        '',
        '切换页对应关系：',
        pageGuide,
        '',
        '每个切换页的动态字段顺序：',
        fieldGuide,
        '',
        '严格输出模板：',
        `<${rule.tagName}>`,
        ...records,
        `</${rule.tagName}>`,
        `</${rule.tagName}_rules>`,
    ].join('\n');
}

export function parseStatusOutput(input, rawOutput) {
    const rule = normalizeRule(input);
    if (isStatusBeauty01To15(rule.structure)) return parseStatusBeautyBundledOutput(rule, rawOutput);
    const source = String(rawOutput || '');
    const block = source.match(new RegExp(`<${rule.tagName}>\\s*([\\s\\S]*?)\\s*<\\/${rule.tagName}>`, 'i'))?.[1] || source;
    const records = {};
    for (const match of block.matchAll(/[\[【]([^\]】\r\n]+)[\]】]/g)) {
        const parts = match[1].replace(/｜/g, '|').split('|').map(value => value.trim());
        const key = parts.shift();
        if (key) records[key] = parts;
    }
    const missing = [];
    if (rule.sharedFields.length && (records.Shared?.length || 0) < rule.sharedFields.length) missing.push('Shared');
    for (const page of rule.pages) {
        if ((records[page.id]?.length || 0) < (page.fields || rule.pageFields).length) missing.push(page.id);
    }
    if (missing.length) throw new Error(`AI 状态区块缺少完整记录：${missing.join('、')}`);
    return {
        rule,
        shared: rule.sharedFields.map((_, index) => records.Shared?.[index] || ''),
        pages: rule.pages.map(page => ({ page, values: (page.fields || rule.pageFields).map((_, index) => records[page.id]?.[index] || '') })),
        raw: source,
    };
}

export function buildWorldbookJson(input) {
    const rule = normalizeRule(input);
    return {
        entries: {
            0: {
                uid: 0,
                key: [],
                keysecondary: [],
                comment: `九一 · ${rule.ruleName} · AI动态输出规则`,
                content: buildAiInstruction(input),
                constant: true,
                vectorized: false,
                selective: true,
                selectiveLogic: 0,
                addMemo: true,
                order: 100,
                position: 4,
                disable: false,
                ignoreBudget: false,
                excludeRecursion: false,
                preventRecursion: false,
                matchPersonaDescription: false,
                matchCharacterDescription: false,
                matchCharacterPersonality: false,
                matchCharacterDepthPrompt: false,
                matchScenario: false,
                matchCreatorNotes: false,
                delayUntilRecursion: 0,
                probability: 100,
                useProbability: true,
                automationId: 'jiuyi-status-output-rule-v1',
                depth: 1,
                outletName: '',
                group: '',
                groupOverride: false,
                groupWeight: 100,
                scanDepth: null,
                caseSensitive: null,
                matchWholeWords: null,
                useGroupScoring: null,
                role: 0,
                sticky: null,
                cooldown: null,
                delay: null,
                triggers: [],
            },
        },
    };
}

function safeJsonForScript(value) {
    return JSON.stringify(value)
        .replace(/</g, '\\u003c')
        .replace(/>/g, '\\u003e')
        .replace(/&/g, '\\u0026');
}

